argv:
$ErrorActionPreference='Stop'
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32TopFix {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
}
"@
$out=New-Object System.Collections.ArrayList
$cb=[W32TopFix+EnumWindowsProc]{
 param($h,$l)
 if([W32TopFix]::IsWindowVisible($h)){
   $tsb=New-Object System.Text.StringBuilder 512
   $csb=New-Object System.Text.StringBuilder 256
   [void][W32TopFix]::GetWindowText($h,$tsb,$tsb.Capacity)
   [void][W32TopFix]::GetClassName($h,$csb,$csb.Capacity)
   [uint32]$procId=0
   [void][W32TopFix]::GetWindowThreadProcessId($h,[ref]$procId)
   $p=Get-Process -Id $procId -ErrorAction SilentlyContinue
   [void]$out.Add([pscustomobject]@{
     hwnd=[string]$h
     title=$tsb.ToString()
     class=$csb.ToString()
     process_id=[int]$procId
     process=[string]$p.ProcessName
   })
 }
 return $true
}
[W32TopFix]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null
$out | ConvertTo-Json -Depth 4 -Compress
